questionvariables.text:
/* --------- Part (a) ---------- */
/*random coordinates of triangle*/
ax:-rand(5)-2;
ay:rand(3)+3;
bx:ax+7+rand(4);
by:ay;
cx:rand_with_prohib(ax+1,bx-1,[0]);
cy:ay+5+rand(5);
/*dimensions of triangle*/
base:bx-ax;
height:cy-by;
areaABC:base*height/2;

/* --------- Part (b) --------- */
de:8+(rand(9)+1)/10;
angleD_degrees:rand_with_step(36,44,1);
angleD_radians:angleD_degrees*pi/180;
ef:rand_with_step(62,68,1)/10;
/* Find coefficients of quadratic on df from cosine rule and then df with quadratic formula */
bb:-2*de*cos(angleD_radians);
cc:de^2-ef^2;
df_calculated:(-bb-sqrt(bb^2-4*cc))/2;
/* Get the value of df to use in the actual question */
df_in_question:floor(10*decimalplaces(df_calculated,1));
df_in_question:df_in_question/10;
df:df_in_question;
/* calcuylate the area */
areaDEF:1/2*df*de*sin(angleD_radians);









/*-------------------------------------------------------------------------------------------*/
/*Define function S(n) that given a number n, returns the string "+n" if positive (or zero) and "-n" if negative, if n=+1 or -1 it returns + or - respectively*/
S(n):= block([], if (n=1) then return("+") elseif (n=-1) then return("-") elseif (n>=0) then return(vconcat("+", abs(n)))  else  return(vconcat("-", abs(n))));

/*Define function S1(n) that given a number n, returns the string "+n" if positive (or zero) and "-n" if negative (1 and -1 are treated as the other numbers)*/
S1(n):= block([], if (n>=0) then return(vconcat("+", abs(n)))  else  return(vconcat("-", abs(n))));

/*Define function SP(n) that given a number n, returns the string "n" if positive (or zero) and "(-n)" if negative*/
SP(n):= block([], if (n>=0) then return(n)  else  return(vconcat("(-", abs(n), ")")));

/*-------------------------------------------------------------------------------------------*/

feedbackvariables.text:
/*Check correct answer if integer or float*/
if_interger:if integerp(areaABC) then areaABC else float(areaABC);

/* Mistake node 2: using side AC as height */
mistake_12:base*sqrt((cx-ax)^2+(cy-ay)^2)/2;

/* Mistake node 3: using side BC as height */
mistake_13:base*sqrt((cx-bx)^2+(cy-by)^2)/2;

/* Mistake node 4: using side AC and BC as base and height */
mistake_14:sqrt((cx-ax)^2+(cy-ay)^2)*sqrt((cx-bx)^2+(cy-by)^2)/2;

/* Mistake node 5: using long method with cos rule and sine rule but carrying rounding errors. */

/* Mistake node 3: Using wrong sides pt1  */
mistake3:1/2*df*ef*sin(angleD_radians);

/* Mistake node 4: Using wrong sides pt2  */
mistake4:1/2*de*ef*sin(angleD_radians);

